import glob, re, collections
codes = collections.Counter()
for path in glob.glob("logs/*.log"):
    for line in open(path):
        match = re.search(r" ERROR \S+ (ERR_[A-Z0-9_]+)\b", line)
        if match:
            codes[match.group(1)] += 1
for code, count in codes.most_common(3):
    print(code, count)
